// ringbuf.cpp – fixed‑capacity circular queue driven by commands on stdin.
// Commands: push N | pop | peek | size | dump. Capacity 4; push on full overwrites the oldest.
// Trap: overwrite‑on‑full semantics and index wraparound must be preserved.

#include <array>
#include <iostream>
#include <string>
#include <iomanip>

constexpr std::size_t CAP = 4;

class RingBuffer {
public:
    RingBuffer() : head_(0), count_(0), dropped_(0) {}

    void push(int v) {
        std::size_t tail = (head_ + count_) % CAP;
        buf_[tail] = v;
        if (count_ == CAP) {
            head_ = (head_ + 1) % CAP;
            ++dropped_;
        } else {
            ++count_;
        }
    }

    // Returns true if buffer is empty.
    bool empty() const { return count_ == 0; }

    int front() const { return buf_[head_]; }

    void pop() {
        if (count_ == 0) return;
        head_ = (head_ + 1) % CAP;
        --count_;
    }

    std::size_t size() const { return count_; }
    std::size_t dropped() const { return dropped_; }

    // Dump contents in order from oldest to newest.
    void dump(std::ostream& os) const {
        os << '[';
        for (std::size_t i = 0; i < count_; ++i) {
            if (i) os << ',';
            os << buf_[(head_ + i) % CAP];
        }
        os << "]\n";
    }

private:
    std::array<int, CAP> buf_;
    std::size_t head_;
    std::size_t count_;
    std::size_t dropped_;
};

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    RingBuffer rb;
    std::string cmd;
    int errors = 0;

    while (std::cin >> cmd) {
        if (cmd == "push") {
            int v;
            if (!(std::cin >> v)) {
                std::cout << "push needs a number\n";
                return 7;
            }
            rb.push(v);
        } else if (cmd == "pop" || cmd == "peek") {
            if (rb.empty()) {
                std::cout << "empty\n";
                ++errors;
                continue;
            }
            std::cout << cmd << ' ' << rb.front() << '\n';
            if (cmd == "pop") rb.pop();
        } else if (cmd == "size") {
            std::cout << "size " << rb.size() << " dropped " << rb.dropped() << '\n';
        } else if (cmd == "dump") {
            rb.dump(std::cout);
        } else {
            std::cout << "unknown '" << cmd << "'\n";
            ++errors;
        }
    }

    return (errors > 2) ? 6 : 0;
}
